CREATE TABLE "attendance_policy" ("id" text PRIMARY KEY NOT NULL, "organizationId" text NOT NULL UNIQUE REFERENCES "organization"("id") ON DELETE CASCADE, "graceMinutes" integer NOT NULL DEFAULT 10, "overtimeAfterMinutes" integer NOT NULL DEFAULT 0, "missingClockOutAfterMinutes" integer NOT NULL DEFAULT 180, "expectedWorkdays" json NOT NULL DEFAULT '[1,2,3,4,5]'::json, "updatedBy" text REFERENCES "user"("id") ON DELETE SET NULL, "createdAt" timestamp NOT NULL DEFAULT now(), "updatedAt" timestamp NOT NULL DEFAULT now());
CREATE TABLE "staff_leave" ("id" text PRIMARY KEY NOT NULL, "organizationId" text NOT NULL REFERENCES "organization"("id") ON DELETE CASCADE, "employeeId" text NOT NULL REFERENCES "employee"("id") ON DELETE CASCADE, "type" text NOT NULL, "startDate" text NOT NULL, "endDate" text NOT NULL, "reason" text NOT NULL, "documentUrl" text, "status" text NOT NULL DEFAULT 'pending', "requestedBy" text NOT NULL REFERENCES "user"("id") ON DELETE RESTRICT, "decidedBy" text REFERENCES "user"("id") ON DELETE RESTRICT, "decidedAt" timestamp, "managerNotes" text, "createdAt" timestamp NOT NULL DEFAULT now(), "updatedAt" timestamp NOT NULL DEFAULT now());
CREATE INDEX "staff_leave_org_date_idx" ON "staff_leave" ("organizationId", "startDate", "endDate");
CREATE INDEX "staff_leave_employee_idx" ON "staff_leave" ("employeeId");
CREATE TABLE "attendance_correction_request" ("id" text PRIMARY KEY NOT NULL, "organizationId" text NOT NULL REFERENCES "organization"("id") ON DELETE CASCADE, "employeeId" text NOT NULL REFERENCES "employee"("id") ON DELETE CASCADE, "attendanceId" text REFERENCES "staff_attendance"("id") ON DELETE CASCADE, "type" text NOT NULL, "requestedValue" json NOT NULL, "reason" text NOT NULL, "status" text NOT NULL DEFAULT 'pending', "requestedBy" text NOT NULL REFERENCES "user"("id") ON DELETE RESTRICT, "decidedBy" text REFERENCES "user"("id") ON DELETE RESTRICT, "decidedAt" timestamp, "decisionNotes" text, "createdAt" timestamp NOT NULL DEFAULT now(), "updatedAt" timestamp NOT NULL DEFAULT now());
CREATE INDEX "attendance_correction_org_status_idx" ON "attendance_correction_request" ("organizationId", "status");
CREATE INDEX "attendance_correction_employee_idx" ON "attendance_correction_request" ("employeeId");
